import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const EVENT_TYPES = new Set(['started', 'succeeded', 'failed']);

function validateEvent(event, lineNumber) {
  if (event === null || typeof event !== 'object' || Array.isArray(event)) {
    throw new Error(`line ${lineNumber}: event must be an object`);
  }
  if (typeof event.id !== 'string' || event.id.length === 0) {
    throw new Error(`line ${lineNumber}: id must be a nonempty string`);
  }
  if (typeof event.job !== 'string' || event.job.length === 0) {
    throw new Error(`line ${lineNumber}: job must be a nonempty string`);
  }
  if (!Number.isSafeInteger(event.attempt) || event.attempt < 1) {
    throw new Error(`line ${lineNumber}: attempt must be a positive safe integer`);
  }
  if (!Number.isSafeInteger(event.seq) || event.seq < 0) {
    throw new Error(`line ${lineNumber}: seq must be a nonnegative safe integer`);
  }
  if (!EVENT_TYPES.has(event.type)) {
    throw new Error(`line ${lineNumber}: invalid event type`);
  }
}

function sameRequiredFields(left, right) {
  return left.id === right.id
    && left.job === right.job
    && left.attempt === right.attempt
    && left.seq === right.seq
    && left.type === right.type;
}

export function reduceEvents(text) {
  if (typeof text !== 'string') {
    throw new Error('input must be a string');
  }

  const eventsById = new Map();
  let duplicates = 0;

  for (const [index, line] of text.split('\n').entries()) {
    if (/^\s*$/.test(line)) continue;

    let event;
    try {
      event = JSON.parse(line);
    } catch (error) {
      throw new Error(`line ${index + 1}: invalid JSON`, { cause: error });
    }
    validateEvent(event, index + 1);

    const previous = eventsById.get(event.id);
    if (previous !== undefined) {
      if (!sameRequiredFields(previous, event)) {
        throw new Error(`line ${index + 1}: conflicting event id ${JSON.stringify(event.id)}`);
      }
      duplicates += 1;
    } else {
      eventsById.set(event.id, event);
    }
  }

  const jobsByName = new Map();
  for (const event of eventsById.values()) {
    let attemptsByNumber = jobsByName.get(event.job);
    if (attemptsByNumber === undefined) {
      attemptsByNumber = new Map();
      jobsByName.set(event.job, attemptsByNumber);
    }

    let attempt = attemptsByNumber.get(event.attempt);
    if (attempt === undefined) {
      attempt = { start: null, terminal: null };
      attemptsByNumber.set(event.attempt, attempt);
    }

    if (event.type === 'started') {
      if (attempt.start !== null) {
        throw new Error(`job ${JSON.stringify(event.job)} attempt ${event.attempt}: repeated start`);
      }
      attempt.start = event;
    } else {
      if (attempt.terminal !== null) {
        throw new Error(`job ${JSON.stringify(event.job)} attempt ${event.attempt}: repeated terminal`);
      }
      attempt.terminal = event;
    }
  }

  const jobs = [];
  for (const [job, attemptsByNumber] of jobsByName) {
    const attempts = [];
    for (const [attemptNumber, events] of attemptsByNumber) {
      if (events.start === null) {
        throw new Error(`job ${JSON.stringify(job)} attempt ${attemptNumber}: orphan terminal`);
      }
      if (events.terminal !== null && events.terminal.seq <= events.start.seq) {
        throw new Error(`job ${JSON.stringify(job)} attempt ${attemptNumber}: terminal seq must follow start seq`);
      }

      attempts.push({
        attempt: attemptNumber,
        status: events.terminal === null ? 'running' : events.terminal.type,
        startedSeq: events.start.seq,
        finishedSeq: events.terminal === null ? null : events.terminal.seq,
      });
    }
    attempts.sort((left, right) => left.attempt - right.attempt);
    jobs.push({ job, attempts });
  }
  jobs.sort((left, right) => left.job < right.job ? -1 : left.job > right.job ? 1 : 0);

  return { jobs, duplicates };
}

function runCli() {
  if (process.argv.length !== 3) {
    throw new Error('usage: node receipt-report.js LOGFILE');
  }
  const text = readFileSync(process.argv[2], 'utf8');
  process.stdout.write(`${JSON.stringify(reduceEvents(text))}\n`);
}

const isMain = process.argv[1] !== undefined
  && resolve(process.argv[1]) === resolve(fileURLToPath(import.meta.url));

if (isMain) {
  try {
    runCli();
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    process.stderr.write(`${message || 'error'}\n`);
    process.exitCode = 2;
  }
}

